require dirname(__DIR__).'/bootstrap.php';require dirname(__DIR__).'/sms.php';method('POST');rate('sms_lostpw',10,600);$c=sms_config();$tel=sms_tel();$code=text_input('code',8);$password=text_input('new_password',256);password_rules($password);$bound=one('SELECT m.uid,m.username FROM '.table('comiis_sms_user').' s JOIN '.table('common_member').' m ON m.uid=s.uid WHERE s.tel=? ORDER BY s.dateline DESC LIMIT 1',[$tel]);if(!$bound)respond(null,422,'手机号未绑定');consume_sms($tel,1,$code,$c);$r=uc_user_edit(addslashes($bound['username']),null,$password,null,1);if($r<0)respond(null,422,'密码修改失败');exec_sql('UPDATE '.table('common_member').' SET password=? WHERE uid=?',[md5(random_bytes(32)),$bound['uid']]);app_schema();exec_sql('DELETE FROM '.table('app_token').' WHERE uid=?',[$bound['uid']]);respond(['reset'=>true]);
